\label{def:ENNReal.log}



The logarithm as a function from $\mathbb{R}_{+, \infty}$ to $\overline{\mathbb{R}}$ is defined as
\begin{align*}
  \log(x)
  &= \begin{cases}
    -\infty & \text{if } x = 0 \\
    \text{the usual logarithm} & \text{if } x \in (0, +\infty) \\
    +\infty & \text{if } x = +\infty
  \end{cases}
\end{align*}

\label{def:eintegral}



For $f : \Omega \to \overline{\mathbb{R}}$ and $\mu$ a measure on $\Omega$, we define the extended integral of $f$ with respect to $\mu$ as
\begin{align*}
  \int_{\omega} f (\omega) \, d\mu
  &:= \int_{\omega} f^{+} (\omega) \, d\mu - \int_{\omega} f^{-} (\omega) \, d\mu
  \: ,
\end{align*}
where $f^{+} = \max(f, 0)$ and $f^{-} = -\min(f, 0)$, and their integrals are Lebesgue integrals, possibly taking the value $+\infty$.

\begin{align*}
  \int_{\omega} f (\omega) \, d\mu
  &:= \int_{\omega} f^{+} (\omega) \, d\mu - \int_{\omega} f^{-} (\omega) \, d\mu
  \: ,
\end{align*}

\label{def:acSet}

  Let $P \in \mathcal{M}(\mathcal{X})$ and let $\mathcal{Q} \subseteq \mathcal{M}(\mathcal{X})$ be a set of measures.
  We say that $P$ is absolutely continuous with respect to $\mathcal{Q}$ (denoted by $P \ll \mathcal{Q}$) if all $\mathcal{Q}$-null sets are $P$-null sets.

\label{lem:nullSet_eq_top}

Let $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$ be a set of probability measures and let $f$ be an E-variable for $\mathcal{Q}$.
Then the set $\{f = \infty\}$ is $\mathcal{Q}$-null.

\label{def:maxUtility}



For a utility function $U$, the maximal utility for $(P, \mathcal{Q})$ is defined as
\begin{align*}
  \mathcal{U}(P, \mathcal{Q})
  &= \sup_{f \in \mathcal{E}_{\mathcal{Q}}} P[U(f)]
  \: ,
\end{align*}
in which the expectation is the extended integral defined in Definition~\ref{def:eintegral}.

\label{lem:maxRandUtility_eq_maxUtility}



Let $U : \mathbb{R}_{+,\infty} \to \overline{\mathbb{R}}$ be a utility function and $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$ a set of probability measures.
Let $P \in \mathcal{P}(\mathcal{X})$. Then
\begin{align*}
  \mathcal{U}^R(P, \mathcal{Q})
  &= \mathcal{U}(P, \mathcal{Q})
  \: .
\end{align*}

\label{lem:maxUtility_eq_top_of_not_acSet}

Suppose that there exists an event $A$ such that $P(A) > 0$ and $Q(A) = 0$ for all $Q \in \mathcal{Q}$. That is, we don't have $P \ll \mathcal{Q}$.
Then
\begin{align*}
  \mathcal{U}(P, \mathcal{Q})
  &= +\infty
  \: .
\end{align*}

\label{lem:eVar_comp}



Let $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$ be a set of probability measures and let $\phi : \mathcal{X} \to \mathcal{Y}$ be a measurable function.
Then for all $g \in \mathcal{E}_{\phi_* \mathcal{Q}}$, $g \circ \phi \in \mathcal{E}_{\mathcal{Q}}$.

\label{lem:randEVar_comp}



Let $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$ be a set of probability measures and let $\kappa : \mathcal{X} \rightsquigarrow \mathcal{Y}$ be a Markov kernel.
Then for all $\xi \in \mathcal{E}_{\kappa \circ \mathcal{Q}}^R$, $\xi \circ \kappa \in \mathcal{E}^R_{\mathcal{Q}}$.

\label{thm:maxRandUtility_comp_le}



Let $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$ be a set of probability measures and $P \in \mathcal{P}(\mathcal{X})$.
Let $U : \mathbb{R}_{+,\infty} \to \overline{\mathbb{R}}$ be a utility function.
Then for all Markov kernels $\kappa : \mathcal{X} \rightsquigarrow \mathcal{Y}$,
\begin{align*}
  \mathcal{U}^R(P, \mathcal{Q})
  &\ge \mathcal{U}^R(\kappa \circ P, \kappa \circ \mathcal{Q})
  \: .
\end{align*}

\label{lem:maxUtility_comp_le}



Let $\kappa : \mathcal{X} \rightsquigarrow \mathcal{Y}$ be a Markov kernel, $P \in \mathcal{P}(\mathcal{X})$ and $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$.
Then
\begin{align*}
  \mathcal{U}(\kappa \circ P, \kappa \circ \mathcal{Q})
  &\le \mathcal{U}(P, \mathcal{Q})
  \: .
\end{align*}

\label{lem:maxUtility_map_le}



Let $f : \mathcal{X} \to \mathcal{Y}$ be a measurable function, $P \in \mathcal{P}(\mathcal{X})$ and $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$.
Then
\begin{align*}
  \mathcal{U}(f_*P, f_* \mathcal{Q})
  &\le \mathcal{U}(P, \mathcal{Q})
  \: .
\end{align*}

\label{lem:maxUtility_map_eq}



Let $\phi : \mathcal{X} \to \mathcal{Y}$ be a measurable embedding, $P \in \mathcal{P}(\mathcal{X})$ and $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$.
Then
\begin{align*}
  \mathcal{U}(\phi_* P, \phi_* \mathcal{Q})
  &= \mathcal{U}(P, \mathcal{Q})
  \: .
\end{align*}

\label{lem:maxUtility_map_swap}



Let $R \in \mathcal{P}(\mathcal{X})$, $\mathcal{P} \subseteq \mathcal{P}(\mathcal{X})$ and let $\phi : \mathcal{X} \to \mathcal{X}$ be a measurable map such that $\phi \circ \phi = \id$.
Then
\begin{align*}
  \mathcal{U}(R, \phi_* \mathcal{P})
  &= \mathcal{U}(\phi_* R, \mathcal{P})
  \: .
\end{align*}

\label{def:IsNumeraire}



Let $P \in \mathcal{P}(\mathcal{X})$ and $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$.
A numeraire for $(P, \mathcal{Q})$ is a $P$-almost surely positive e-variable $f^* \in \mathcal{E}_{\mathcal{Q}}$ such that $P[f / f^*] \le 1$ for all $f \in \mathcal{E}_{\mathcal{Q}}$~.

\label{lem:IsNumeraire.eintegral_log_div_nonpos}



Let $f^*$ be a numeraire for $(P, \mathcal{Q})$ and let $f \in \mathcal{E}_{\mathcal{Q}}$.
Then $P\left[\log \frac{f}{f^*}\right] \le 0$.

\label{lem:numeraire_iff_logOptimal}

Let $f$ be a $P$-almost surely positive E-variable for a set of probability measures $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$.
Then $f$ is a numeraire for $(P, \mathcal{Q})$ if and only if $P[\log \frac{g}{f}] \le 0$ for all $g \in \mathcal{E}_{\mathcal{Q}}$.

\label{lem:IsNumeraire.eintegral_log_le}



Let $f^*$ be a numeraire for $(P, \mathcal{Q})$.
Then for all $f \in \mathcal{E}_{\mathcal{Q}}$,
\begin{align*}
  P[\log f]
  &\le P[\log f^*]
  \: .
\end{align*}

\label{lem:IsNumeraire.eintegral_log_nonneg}



Let $f^*$ be a numeraire for $(P, \mathcal{Q})$.
Then $P[\log f^*] \ge 0$.

\label{lem:maxUtility_eq_integral}



