\label{lem:convex_effectiveSet}

  Let $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$ be a set of probability measures.
The effective set $\mathcal{Q}_{\eff}$ is convex and satisfies $0 \in \mathcal{Q}_{\eff}$ and $\mathcal{Q} \subseteq \mathcal{Q}_{\eff}$.

\begin{align*}
  \{Q\}_{\eff}
  &= \{Q' \in \mathcal{M}(\mathcal{X}) \mid \forall f, \ (\forall Q'' \in \{Q\}, Q''[f] \le 1) \implies Q'[f] \le 1\}
  \\
  &= \{Q' \in \mathcal{M}(\mathcal{X}) \mid \forall f, \ Q[f] \le 1 \implies Q'[f] \le 1\}
\end{align*}
This is the set of finite measures $\{Q' \mid Q' \le Q\}$.
Indeed, if $Q' \le Q$, then for all $f$ with $Q[f] \le 1$, $Q'[f] \le Q[f] \le 1$.
Conversely, if $Q'$ is such that $(\forall f, \ Q[f] \le 1 \implies Q'[f] \le 1)$, then for any measurable set $A$, we can take the measurable function $f = Q(A)^{-1} \cdot \mathbb{I}_A$ (in which $0^{-1} = \infty$) to obtain $Q'(A) \le Q(A)$.

\begin{align*}
  \{Q\}_{\eff}
  &= \{Q' \in \mathcal{M}(\mathcal{X}) \mid \forall f, \ (\forall Q'' \in \{Q\}, Q''[f] \le 1) \implies Q'[f] \le 1\}
  \\
  &= \{Q' \in \mathcal{M}(\mathcal{X}) \mid \forall f, \ Q[f] \le 1 \implies Q'[f] \le 1\}
\end{align*}

\label{lem:effectiveSet_comp_subset}

Let $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$ and let $\kappa : \mathcal{X} \rightsquigarrow \mathcal{Y}$ be a Markov kernel.
Then $\kappa \circ \mathcal{Q}_{\eff} \subseteq (\kappa \circ \mathcal{Q})_{\eff}$.

\begin{align*}
  \kappa \circ \mathcal{Q}_{\eff}
  &= \{\kappa \circ Q \mid \forall f, (\forall Q' \in \mathcal{Q}, Q'[f] \le 1) \implies Q[f] \le 1\}
  \\
  (\kappa \circ \mathcal{Q})_{\eff}
  &= \{R \mid \forall f, (\forall Q' \in \mathcal{Q}, (\kappa \circ Q')[f] \le 1) \implies R[f] \le 1\}
\end{align*}

Let $\kappa \circ Q \in \kappa \circ \mathcal{Q}_{\eff}$ and $f$ such that $\forall Q' \in \mathcal{Q}, (\kappa \circ Q')[f] \le 1$. That is, $\forall Q' \in \mathcal{Q}, Q'[x \mapsto \kappa(x)[f]] \le 1$.
Then since $Q \in \mathcal{Q}_{\eff}$, we have $Q[x \mapsto \kappa(x)[f]] \le 1$.
We have proved that $\kappa \circ Q \in (\kappa \circ \mathcal{Q})_{\eff}$.

\begin{align*}
    \kappa \circ \mathcal{Q}_{\eff}
    &= \{\kappa \circ Q \mid \forall f, (\forall Q' \in \mathcal{Q}, Q'[f] \le 1) \implies Q[f] \le 1\}
    \\
    (\kappa \circ \mathcal{Q})_{\eff}
    &= \{R \mid \forall f, (\forall Q' \in \mathcal{Q}, (\kappa \circ Q')[f] \le 1) \implies R[f] \le 1\}
  \end{align*}

\label{lem:effectiveSet_mono}

Let $\mathcal{Q}_1 \subseteq \mathcal{Q}_2 \subseteq \mathcal{P}(\mathcal{X})$ be two sets of probability measures.
Then $\mathcal{Q}_{1, \eff} \subseteq \mathcal{Q}_{2, \eff}$.


Since $\mathcal{Q}_1 \subseteq \mathcal{Q}_2$ we have $\mathcal{E}_{\mathcal{Q}_2} \subseteq \mathcal{E}_{\mathcal{Q}_1}$ (Lemma~\ref{lem:eVarSet_anti}).
Then
\begin{align*}
  \mathcal{Q}_{1, \eff}
  &= \{\mu \in \mathcal{M}_+(\mathcal{X}) \mid \forall f \in \mathcal{E}_{\mathcal{Q}_1}, \: \mu[f] \le 1\}
  \\
  &\subseteq \{\mu \in \mathcal{M}_+(\mathcal{X}) \mid \forall f \in \mathcal{E}_{\mathcal{Q}_2}, \: \mu[f] \le 1\}
  \\
  &= \mathcal{Q}_{2, \eff}
  \: .
\end{align*}

Let $\KL(P, Q)$ be the Kullback-Leibler divergence from $P$ to $Q$, defined for finite measures as
\begin{align*}
  \KL(P, Q)
  &= \begin{cases}
    P[\log \frac{dP}{dQ}] & \text{if } P \ll Q \\
    +\infty & \text{otherwise}
  \end{cases}
  \: .
\end{align*}

\label{thm:eVar_KL_duality}

Let $P \in \mathcal{P}(\mathcal{X})$ and $\mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$.
If $P \ll \mathcal{Q}$ then
\begin{align*}
  P[\log E^*_{P, \mathcal{Q}}]
  = \sup_{f \in \mathcal{E}_{\mathcal{Q}}} P[\log f]
  = \inf_{\mu \in \mathcal{Q}_{\eff}} \KL(P, \mu)
  = \KL(P, P^*_{\mathcal{Q}})
  \: .
\end{align*}

\label{lem:sup_eVar_singleton}

Let $P, Q \in \mathcal{P}(\mathcal{X})$ be two probability measures with $P \ll Q$.
Then
\begin{align*}
  \sup_{f \in \mathcal{E}_{\{Q\}}} P[\log f]
  = \KL(P, Q)
  \: .
\end{align*}


Since $\KL$ is non-increasing in the second argument,
\begin{align*}
  \inf_{Q' \le Q} \KL(P, Q') = \KL(P, Q) \: .
\end{align*}
Since $\{Q\}_{\eff} = \{Q' \in \mathcal{M}(\mathcal{X}) \mid Q' \le Q\}$ (Lemma~\ref{lem:effectiveSet_singleton}), we obtained $\KL(P, Q) = \inf_{Q' \in \{Q\}_{\eff}} \KL(P, Q')$.
By the duality of numeraire and $\KL$ divergence (Theorem~\ref{thm:eVar_KL_duality}), we have
\begin{align*}
  \sup_{f \in \mathcal{E}_{\{Q\}}} P[\log f]
  = \inf_{Q' \in \{Q\}_{\eff}} \KL(P, Q')
  = \KL(P, Q)
  \: .
\end{align*}

\label{thm:dataprocessing_kl}

  Let $P, Q \in \mathcal{P}(\mathcal{X})$.
  Then for all Markov kernels $\kappa : \mathcal{X} \rightsquigarrow \mathcal{Y}$,
  \begin{align*}
    \KL(P, Q)
    &\ge \KL(\kappa \circ P, \kappa \circ Q)
    \: .
  \end{align*}

\label{def:erenyiDiv}



The e-Rényi divergence of order $\alpha \in (0,1)$ between two sets of probability measures $\mathcal{P}, \mathcal{Q} \subseteq \mathcal{P}(\mathcal{X})$ is defined as
\begin{align*}
  \eR_\alpha(\mathcal{P}, \mathcal{Q})
  &= \frac{1}{1 - \alpha} \inf_{R \in \mathcal{P}(\mathcal{X})} \left( \alpha \mathcal{U}(R, \mathcal{P}) + (1 - \alpha) \mathcal{U}(R, \mathcal{Q}) \right)
  \: ,
\end{align*}
for $\mathcal{U}_{\log}$ the max-utility corresponding to the logarithmic utility.

\label{lem:erenyiDiv_map_le}



Let $f : \mathcal{X} \to \mathcal{Y}$ be a measurable map. Then
\begin{align*}
  \eR_\alpha(f_*\mathcal{P}, f_*\mathcal{Q})
  &\le \eR_\alpha(\mathcal{P}, \mathcal{Q})
  \: .
\end{align*}

\label{lem:echernoffDiv_map_le}



Let $f : \mathcal{X} \to \mathcal{Y}$ be a measurable map. Then
\begin{align*}
  \eC_\alpha(f_*\mathcal{P}, f_*\mathcal{Q})
  &\le \eC_\alpha(\mathcal{P}, \mathcal{Q})
  \: .
\end{align*}

\label{lem:erenyiDiv_eq_iInf_acSet}

For $\alpha \in (0,1)$, if $\eR_\alpha(\mathcal{P}, \mathcal{Q}) < \infty$, then
\begin{align*}
  \eR_\alpha(\mathcal{P}, \mathcal{Q})
  &= \frac{1}{1 - \alpha} \inf_{R \in \mathcal{P}(\mathcal{X}), \: R \ll \mathcal{P}, \: R \ll \mathcal{Q}} \left( \alpha \mathcal{U}_{\log}(R, \mathcal{P}) + (1 - \alpha) \mathcal{U}_{\log}(R, \mathcal{Q}) \right)
  \: .
\end{align*}
That is, the infimum defining $\eR_\alpha(\mathcal{P}, \mathcal{Q})$ can be restricted to measures $R$ that are absolutely continuous with respect to both $\mathcal{P}$ and $\mathcal{Q}$.

